    final int BG=Color.rgb(5,10,16), CARD=Color.rgb(13,27,39), CARD2=Color.rgb(19,41,56), TEXT=Color.rgb(245,249,252), MUTED=Color.rgb(174,196,211), ACC=Color.rgb(54,196,216), RED=Color.rgb(235,91,91), GREEN=Color.rgb(76,207,139);
    final Map<String,TextView> fields=new LinkedHashMap<>();
